const state={menu:'overview',tab:'today',unit:'all',dept:'all',role:'ho',actor:'sarah',query:'',status:'all',kind:'all',filterOpen:false,hideFilters:false,sideOpen:false,sort:'newest',detail:null,picker:null,decision:null,form:null,period:'September 2026'};
const isHO=()=>state.role==='ho', actorName=()=>isHO()?(state.actor==='sarah'?'Sarah Pramesti':'Maya Anggraini'):'Rina Kusuma';
const scoped=x=>(isHO()?(state.unit==='all'||x.unit===state.unit):x.unit==='s01')&&(state.dept==='all'||x.dept===state.dept);
const visibleMenus=()=>menus.filter(m=>!m.ho||isHO());
function tabs(){return menus.find(m=>m.id===state.menu).tabs.filter(t=>t[0]!=='cost'||isHO())}
function inRequests(r){if(!scoped(r))return false;const t=state.tab,m=state.menu;if(m==='overview'){if(t==='approvals')return canDecide(r)&&r.status==='pending';if(t==='attention')return ['returned','blocked'].includes(r.status);return true}if(m==='employees'){if(t==='new')return r.type==='hire';if(t==='changes')return ['salary','adjustment','transfer','contract'].includes(r.type);if(t==='placement')return ['contract','transfer'].includes(r.type);if(t==='onboarding')return r.type==='hire'&&r.status==='approved';if(t==='offboarding')return r.type==='offboarding';if(t==='access')return r.type==='access'}if(m==='time')return r.type==='correction';if(m==='leave')return r.type===(t==='overtime'?'overtime':'leave');return true}
function canDecide(r){return isHO()?(!['leave','overtime'].includes(r.type)||r.unit==='ho'):r.type==='leave'&&r.unit==='s01'}
function visibleRequests(){let rows=requests.filter(inRequests).filter(r=>(state.status==='all'||r.status===state.status)&&(state.kind==='all'||r.type===state.kind)&&`${r.name} ${r.id} ${typeLabels[r.type]}`.toLowerCase().includes(state.query.toLowerCase()));if(state.sort==='oldest')rows=rows.slice().reverse();return rows}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function go(menu,tab){if(!visibleMenus().some(m=>m.id===menu)){toast('Halaman ini hanya tersedia untuk HR HO.');return}state.menu=menu;state.tab=tabs().some(t=>t[0]===tab)?tab:menus.find(m=>m.id===menu).tabs[0][0];state.query='';state.status='all';state.kind='all';state.sideOpen=false;history.replaceState(null,'',`#/people/${menu}/${state.tab}`);render()}
function shell(){const menu=menus.find(m=>m.id===state.menu),pending=requests.filter(r=>scoped(r)&&canDecide(r)&&r.status==='pending').length;return `<header class="header"><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="Buka navigasi">${icon('menu')}</button><a class="brand" href="#/people/overview/today"><span class="mark">i.</span>itulah</a><nav class="global-nav" aria-label="Workspace"><button data-action="workspace-info">Workplace</button><button data-action="workspace-info">Buying</button><button class="active" data-action="home">People</button><button data-action="workspace-info">Finance</button><button data-action="workspace-info">System</button></nav><div class="header-end"><span class="demo-pill">DESIGN PREVIEW</span><button class="icon-btn" data-action="notifications" aria-label="Notifikasi">${icon('bell')}</button><button class="avatar" data-action="role" aria-label="Ganti peran demo">${initials(actorName())}</button></div></header><div class="layout"><aside class="sidebar ${state.sideOpen?'open':''}"><div class="workspace-label">${icon('users')} People</div><div class="side-caption">Your people, in one place.</div><nav aria-label="Menu People">${visibleMenus().map((m,i)=>`${i===5?'<div class="nav-sep"></div>':''}<button class="nav-item ${state.menu===m.id?'active':''}" data-menu="${m.id}" ${state.menu===m.id?'aria-current="page"':''}>${icon(m.icon)}${m.label}${m.id==='overview'&&pending?`<small>${pending}</small>`:''}</button>`).join('')}</nav><div class="side-bottom"><button class="nav-item" data-action="menu-map">${icon('file')} Rancangan menu final</button><div class="org-card"><strong>1 head office · 13 stores</strong><p>DC berada di bawah Head Office.<br>Satu organisasi, satu catatan karyawan.</p></div><button class="role-button" data-action="role"><span class="avatar">${initials(actorName())}</span><span><strong>${actorName()}</strong><small>${isHO()?'HR HO · Semua unit':'HR Store · Store 01'}</small></span>${icon('down')}</button></div></aside><main class="main"><div class="content"><div class="breadcrumb">People ${icon('chevron')} ${menu.label}</div><div class="page-head"><div><h1>${menu.title}</h1><p class="sub">${menu.desc}</p></div><div class="head-actions">${btn(icon('download')+' Ekspor','export')}${state.menu==='setup'?btn(icon('plus')+' Kebijakan','setup-new','primary'):btn(icon('plus')+' Buat pengajuan','create','primary')}</div></div><div class="scope-control">${btn(icon(isHO()?'building':'lock')+' '+(isHO()?unitName(state.unit):'Store 01')+' '+icon('down'),'unit','',isHO()?'':'disabled')}${state.unit==='ho'?btn((state.dept==='all'?'Kantor & DC':state.dept==='dc'?'Distribution Center':'Kantor HO')+' '+icon('down'),'department'):''}<span class="scope-note">${state.unit==='all'?'14 unit operasional · DC termasuk HO':state.unit==='ho'?'Kelola karyawan kantor pusat dan DC':'Data dan pengajuan untuk unit ini'}</span><div style="margin-left:auto">${btn(icon('calendar')+' '+state.period,'period')}</div></div>${state.menu==='overview'?stats():''}<div class="tabs" role="tablist">${tabs().map(([id,label])=>`<button class="tab ${id===state.tab?'active':''}" role="tab" aria-selected="${id===state.tab}" data-tab="${id}">${label}${id==='approvals'?`<span class="count">${pending}</span>`:''}</button>`).join('')}</div><div class="work-grid ${state.hideFilters||state.menu==='setup'||state.menu==='reports'||state.menu==='time'&&['roster','attendance'].includes(state.tab)||state.menu==='leave'&&state.tab==='balances'?'filters-hidden':''}"><section class="list-area">${mainView()}</section>${!state.hideFilters&&state.menu!=='setup'&&!(state.menu==='reports'||state.menu==='time'&&['roster','attendance'].includes(state.tab)||state.menu==='leave'&&state.tab==='balances')?filters():''}</div><footer class="page-footer"><span>Data contoh · 13 September 2026</span><span>${isHO()?'HR HO':'HR Store'} · ${unitName(state.unit)} · People workspace</span></footer></div></main></div><div class="filter-backdrop ${state.filterOpen?'active':''}" data-action="filters"></div>`}
function stats(){const em=employees.filter(scoped),req=requests.filter(scoped),pending=req.filter(r=>r.status==='pending'&&canDecide(r)).length,attention=req.filter(r=>['returned','blocked'].includes(r.status)).length,ps=periods.filter(p=>scoped({...p,dept:state.dept}));return `<div class="stats"><button class="stat" data-nav="employees:directory"><div class="stat-label">Karyawan aktif ${icon('users')}</div><div class="stat-value">${em.length}<small>karyawan</small></div><div class="stat-foot">${em.filter(e=>e.dept==='dc').length} di DC · ${em.filter(e=>e.dept==='office').length} di kantor pusat</div></button><button class="stat" data-tab="approvals"><div class="stat-label">Menunggu keputusan ${icon('file')}</div><div class="stat-value">${pending}<small>pengajuan</small></div><div class="stat-foot blue">Tinjau persetujuan saya →</div></button><button class="stat" data-tab="attention"><div class="stat-label">Perlu perhatian ${icon('clock')}</div><div class="stat-value">${attention}<small>perlu tindak lanjut</small></div><div class="stat-foot">Revisi pengajuan & kelengkapan data</div></button><button class="stat" data-nav="time:periods"><div class="stat-label">Periode ditutup ${icon('calendar')}</div><div class="stat-value">${ps.filter(p=>p.status==='closed').length}<small>/ ${ps.length} unit</small></div><div class="stat-foot">September 2026 · kesiapan payroll</div></button></div>`}
function toolbar(placeholder='Cari nama atau nomor pengajuan…'){return `<div class="toolbar"><label class="search">${icon('search')}<input id="table-search" aria-label="Cari data" placeholder="${placeholder}" value="${esc(state.query)}"></label><div class="toolbar-end">${btn(icon('filter')+' Filter','filters')}${requestContext()?btn(state.sort==='newest'?'Terbaru '+icon('down'):'Terlama '+icon('down'),'sort'):''}</div></div>${state.status!=='all'||state.kind!=='all'?`<div class="chip-row">${state.status!=='all'?`<button class="chip" data-action="reset-filter">${statusLabels[state.status]} ×</button>`:''}${state.kind!=='all'?`<button class="chip" data-action="reset-filter">${typeLabels[state.kind]} ×</button>`:''}</div>`:''}`}
function requestContext(){return state.menu==='overview'||state.menu==='employees'&&state.tab!=='directory'||state.menu==='leave'&&state.tab!=='balances'||state.menu==='time'&&state.tab==='corrections'}
function filters(){return `<aside class="filter-panel ${state.filterOpen?'mobile-open':''}" aria-label="Filter data"><div class="filter-head"><h3>${icon('filter')} Filter</h3><button class="link-button" data-action="reset-filter">Reset</button><button class="icon-btn filter-mobile-close" data-action="filters" aria-label="Tutup filter">${icon('x')}</button></div><div class="filter-body"><label class="field">Status${btn((state.status==='all'?'Semua status':statusLabels[state.status])+icon('down'),'filter-status','field-button')}</label>${requestContext()?`<label class="field">Jenis pengajuan${btn((state.kind==='all'?'Semua jenis':typeLabels[state.kind])+icon('down'),'filter-kind','field-button')}</label>`:''}<label class="field">Unit${btn(unitName(state.unit)+icon('down'),'unit','field-button',isHO()?'':'disabled')}</label><div class="nav-sep" style="margin:23px 0"></div><div class="filter-section-title">Tampilan cepat</div><button class="saved-view" data-view="pending">Menunggu review ${icon('chevron')}</button><button class="saved-view" data-view="returned">Dikembalikan ${icon('chevron')}</button><button class="saved-view" data-view="blocked">Data belum lengkap ${icon('chevron')}</button></div><div class="filter-bottom">Filter mengikuti unit yang dipilih.<br>${isHO()?'Akses Anda mencakup seluruh organisasi.':'Akses Anda terbatas di Store 01.'}</div></aside>`}
function table(headers,rows,foot=''){return `<div class="table-card"><div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${rows.length?'':`<div class="empty">${icon('search')}<h3>Tidak ada data yang sesuai</h3><p>Coba kata pencarian lain atau hapus filter untuk melihat data kembali.</p>${btn('Hapus filter','reset-filter')}</div>`}<div class="table-foot"><span>${rows.length} ${foot||'data ditampilkan'}</span><span>Data contoh <span style="margin-left:14px">1 / 1</span></span></div></div>`}
function requestTable(){return table(['Pengajuan','Unit','Pengaju','Status',''],visibleRequests().map(r=>`<tr data-open="request:${r.id}" tabindex="0" role="button" aria-label="Buka ${r.id}"><td><span class="primary-cell">${r.name}</span><span class="secondary-cell">${typeLabels[r.type]} <span class="mono">· ${r.id}</span></span></td><td>${unitName(r.unit)}<span class="secondary-cell">${r.dept==='dc'?'Distribution Center':r.dept==='office'?'Kantor pusat':'Store operations'}</span></td><td>${r.by}<span class="secondary-cell">${r.date} · v${r.version}</span></td><td>${badge(r.status)}</td><td>${icon('chevron')}</td></tr>`),'pengajuan')}
function employeeTable(){const em=employees.filter(scoped).filter(e=>`${e.name} ${e.id} ${e.job}`.toLowerCase().includes(state.query.toLowerCase())).filter(e=>state.status==='all'||e.status===state.status);return table(['Karyawan','Unit & jabatan','Kontrak','Akun',''],em.map(e=>`<tr data-open="employee:${e.id}" tabindex="0" role="button" aria-label="Buka ${e.name}"><td><div class="person"><span class="avatar ${e.dept==='dc'?'peach':''}">${initials(e.name)}</span><div><span class="primary-cell">${e.name}</span><span class="secondary-cell mono">${e.id}</span></div></div></td><td>${unitName(e.unit)}${e.dept==='dc'?' · DC':''}<span class="secondary-cell">${e.job}</span></td><td>${e.contract}<span class="secondary-cell">${e.end==='—'?'Tetap':'Berakhir '+e.end}</span></td><td>${badge(e.account==='Aktif'?'active':'draft')}</td><td>${icon('chevron')}</td></tr>`),'karyawan')}
function unitOverview(){return `<section class="section-block"><div class="section-header"><h2>Kesiapan periode</h2><button class="link-button" data-nav="time:periods">Lihat semua unit →</button></div><div class="unit-cards">${periods.filter(p=>state.unit==='all'||p.unit===state.unit).slice(0,3).map(p=>`<button class="unit-card" data-open="period:${p.id}"><div class="unit-card-top"><h3>${unitName(p.unit)}</h3>${badge(p.status)}</div><p class="sub">${p.issues?`${p.issues} pengecualian perlu diselesaikan`:'Periksa kelengkapan data periode'}</p><div class="progress"><span style="width:${p.status==='closed'?100:p.issues?55:80}%"></span></div><span class="quiet">${p.punch} · September</span></button>`).join('')}</div></section>`}
function mainView(){if(state.menu==='setup')return setupView();if(state.menu==='employees'&&state.tab==='directory')return toolbar('Cari nama, nomor, atau jabatan…')+`<div id="results">${employeeTable()}</div>`;if(state.menu==='time'){if(state.tab==='roster')return rosterView();if(state.tab==='attendance')return `<div class="notice warn">${icon('info')}Sumber presensi belum terhubung di Hub. Jadwal kerja bukan bukti kehadiran; data aktual belum dinilai.</div><div class="table-card"><div class="empty">${icon('calendar')}<h3>Menunggu sumber presensi</h3><p>Setelah sumber terhubung, catatan masuk, keluar, dan pengecualian akan tampil di sini.</p>${btn('Lihat roster','roster')}</div></div>`;if(state.tab==='periods')return toolbar('Cari unit…')+`<div id="results">${periodTable()}</div>`}if(state.menu==='payroll')return toolbar('Cari karyawan atau unit…')+`<div id="results">${state.tab==='runs'?payrollTable():agreementTable()}</div>`;if(state.menu==='reports')return reportView();if(state.menu==='leave'&&state.tab==='balances')return toolbar('Cari karyawan…')+`<div id="results">${balanceTable()}</div>`;return `${state.menu==='employees'&&state.tab==='access'?`<div class="notice">${icon('shield')}HR mengajukan dan menyetujui kebutuhan akses. Aktivasi akun serta pemberian hak dijalankan oleh System setelah persetujuan.</div>`:''}${state.menu==='leave'&&state.tab==='overtime'?`<div class="notice">${icon('info')}Perintah atasan dan kesediaan karyawan dicatat terpisah. HR tidak memberikan persetujuan atas nama karyawan.</div>`:''}${toolbar()}<div id="results">${requestTable()}</div>${state.menu==='overview'&&state.tab==='today'?unitOverview():''}`}
function periodTable(){return table(['Unit','Periode','Presensi','Pengecualian','Status',''],periods.filter(p=>scoped({...p,dept:state.dept})&&unitName(p.unit).toLowerCase().includes(state.query.toLowerCase())&&(state.status==='all'||p.status===state.status)).map(p=>`<tr data-open="period:${p.id}" tabindex="0" role="button"><td><span class="primary-cell">${unitName(p.unit)}</span><span class="secondary-cell">${p.unit==='ho'?'Kantor & DC':'HR unit'}</span></td><td>${p.month}</td><td>${p.punch}</td><td>${p.issues?`${p.issues} terbuka`:'Tidak ada'}</td><td>${badge(p.status)}</td><td>${icon('chevron')}</td></tr>`))}
function payrollTable(){return `<div class="notice">${icon('shield')}Verifikasi dan persetujuan harus dilakukan orang berbeda. Payroll yang belum lengkap tidak dapat dikunci atau dikirim ke Finance.</div>`+table(['Payroll run','Unit','Neto contoh','Status',''],payroll.filter(p=>scoped({...p,dept:state.dept})&&(state.status==='all'||p.status===state.status)&&`${p.id} ${unitName(p.unit)}`.toLowerCase().includes(state.query.toLowerCase())).map(p=>`<tr data-open="payroll:${p.id}" tabindex="0" role="button"><td><span class="primary-cell">${p.month}</span><span class="secondary-cell mono">${p.id} · v${p.version}</span></td><td>${unitName(p.unit)}</td><td>${p.status==='blocked'?'Belum dihitung':money(p.amount)}</td><td>${badge(p.status)}</td><td>${icon('chevron')}</td></tr>`))}
function agreementTable(){return table(['Karyawan','Unit','Gaji pokok contoh','Berlaku sejak',''],employees.filter(scoped).filter(e=>e.name.toLowerCase().includes(state.query.toLowerCase())).map(e=>`<tr data-open="employee:${e.id}" tabindex="0" role="button"><td><span class="primary-cell">${e.name}</span><span class="secondary-cell">${e.id}</span></td><td>${unitName(e.unit)}</td><td>${money(e.salary)}</td><td>01 Sep 2026</td><td>${icon('chevron')}</td></tr>`))}
function balanceTable(){return table(['Karyawan','Unit','Hak contoh','Terpakai','Saldo'],employees.filter(scoped).filter(e=>e.name.toLowerCase().includes(state.query.toLowerCase())).map((e,i)=>`<tr><td><span class="primary-cell">${e.name}</span><span class="secondary-cell">Cuti tahunan · kebijakan demo</span></td><td>${unitName(e.unit)}</td><td>12 hari</td><td>${i%5} hari</td><td>${12-i%5} hari</td></tr>`))}
function rosterView(){const es=employees.filter(scoped).slice(0,8);return `<div class="toolbar"><h3>14 – 20 September 2026</h3><span class="quiet">Senin – Minggu</span><div class="toolbar-end">${btn(icon('plus')+' Atur jadwal','new-roster')}</div></div><div class="notice">${icon('info')}Roster berikut adalah rencana kerja contoh. Kehadiran aktual tetap menunggu sumber presensi.</div><div class="roster">${table(['Karyawan','Sen 14','Sel 15','Rab 16','Kam 17','Jum 18','Sab 19','Min 20'],es.map((e,i)=>`<tr><td><span class="primary-cell">${e.name}</span><span class="secondary-cell">${unitName(e.unit)}${e.dept==='dc'?' · DC':''}</span></td>${Array.from({length:7},(_,d)=>`<td><span class="shift ${d===(i%7)?'off':''}">${rosterEdits[e.id]?.date==='2026-09-'+String(14+d)?({pagi:'09.00–17.00',dc:'06.00–14.00',libur:'Libur'}[rosterEdits[e.id].shift]):d===(i%7)?'Libur':e.dept==='dc'?'06.00–14.00':'09.00–17.00'}</span></td>`).join('')}</tr>`),'karyawan pada preview minggu')}</div>`}
function reportView(){if(state.tab==='cost')return `<div class="notice">${icon('info')}Angka berikut adalah nominal contoh per unit. Komponen payroll produksi belum dihitung dalam prototype.</div>${payrollTable()}`;if(state.tab==='absence')return periodTable();const groups=units.filter(u=>state.unit==='all'||u.id===state.unit).map(u=>({name:u.name,count:employees.filter(e=>e.unit===u.id&&scoped(e)).length}));return `<div class="table-card"><div style="padding:20px;border-bottom:1px solid var(--line)"><h2>Distribusi karyawan aktif</h2><p class="sub">${employees.filter(scoped).length} karyawan contoh · unit kerja, bukan hak akses</p></div><div class="report-bars">${groups.map(g=>`<div class="report-row"><span>${g.name}</span><div class="report-bar"><span style="width:${g.count/7*100}%"></span></div><strong>${g.count}</strong></div>`).join('')}</div></div>`}
function setupView(){const t=state.tab;if(t==='responsibility')return table(['Unit','Bagian','HR unit','Reviewer pusat'],units.map((u,i)=>`<tr><td><span class="primary-cell">${u.name}</span></td><td>${u.id==='ho'?'Kantor HO + DC':'Store operations'}</td><td>${u.id==='ho'?'Nadia Safitri':i===1?'Rina Kusuma':'HR '+u.name}</td><td>HR HO · sesuai mandat</td></tr>`));const cards=t==='policy'?[['clock','Kebijakan presensi','Toleransi, pasangan punch, dan tanggal berlaku.'],['calendar','Pola shift','Jam mulai, selesai, jeda, dan lintas tengah malam.'],['file','Jenis cuti','Jenis hak, bukti, dan kebijakan pemakaian.'],['calendar','Kalender libur','Tanggal, lingkup unit, publikasi, dan perubahan.']]:t==='components'?[['wallet','Gaji pokok','Bersumber dari kesepakatan gaji yang berlaku.'],['plus','Tunjangan & penyesuaian','Komponen usulan dan dasar keputusan HO.'],['shield','Potongan & kewajiban','Perlu konfigurasi resmi sebelum perhitungan final.'],['file','Sumber & kelengkapan','Komponen belum dinilai tidak dianggap nol.']]:[['users','HR unit','Operasional karyawan pada unit yang ditugaskan.'],['shield','HR HO','Keputusan pengajuan dan kebijakan lintas unit.'],['wallet','Reviewer payroll','Verifikator dan approver harus berbeda orang.'],['lock','System & Finance','System mengeksekusi akses; Finance mengeksekusi pembayaran.']];return `<div class="settings-grid">${cards.map(([ic,n,d])=>`<button class="setting-card" data-setting="${n}">${icon(ic)}<h3>${n}</h3><p>${d}</p><footer>Lihat rancangan kebijakan →</footer></button>`).join('')}</div>`}
function render(){if(!visibleMenus().some(m=>m.id===state.menu)){state.menu='overview';state.tab='today'}$('#app').innerHTML=shell()}
function refreshResults(){const el=$('#results');if(!el){render();return}el.innerHTML=state.menu==='employees'&&state.tab==='directory'?employeeTable():state.menu==='time'&&state.tab==='periods'?periodTable():state.menu==='payroll'?(state.tab==='runs'?payrollTable():agreementTable()):state.menu==='leave'&&state.tab==='balances'?balanceTable():requestTable()}
function showSheet(title,subtitle,body,footer,meta=''){const d=$('#sheet');d.innerHTML=`<header class="sheet-head"><div>${meta?`<div class="sheet-meta">${meta}</div>`:''}<h2>${esc(title)}</h2><p class="sub">${subtitle}</p></div><button class="icon-btn" data-action="close-sheet" aria-label="Tutup detail">${icon('x')}</button></header><div class="sheet-body">${body}</div><footer class="sheet-foot">${footer||btn('Tutup','close-sheet')}</footer>`;if(!d.open)d.showModal()}
function closeSheet(){if(state.form){showDiscard();return}$('#sheet').close();state.detail=null;state.decision=null}
function showDiscard(){picker('discard','Tutup formulir?',[['keep','Lanjutkan mengisi','Kembali ke formulir'],['discard','Buang isian','Isian yang belum disimpan akan hilang']],false)}
function picker(kind,title,items,search=true){state.picker={kind,title,items};const d=$('#picker');d.innerHTML=`<div class="picker-head"><h2>${title}</h2><button class="icon-btn" data-action="close-picker" aria-label="Tutup pilihan">${icon('x')}</button></div>${kind==='role'?'<p class="picker-description">Pengalih peran khusus prototype. Hak akses produksi ditentukan oleh server.</p>':''}${search?`<label class="search picker-search">${icon('search')}<input id="picker-query" aria-label="Cari pilihan" placeholder="Cari pilihan…" autocomplete="off"></label>`:''}<div class="picker-list" id="picker-results">${pickerRows('')}</div>`;if(!d.open)d.showModal();$('#picker-query')?.focus()}
function pickerRows(q){const p=state.picker,rows=p.items.filter(i=>`${i[1]} ${i[2]||''}`.toLowerCase().includes(q.toLowerCase()));return rows.length?rows.map(([id,label,desc])=>`<button class="picker-item" data-pick="${esc(id)}"><span>${esc(label)}${desc?`<small>${esc(desc)}</small>`:''}</span>${icon('chevron')}</button>`).join(''):'<div class="empty"><h3>Tidak ada pilihan</h3><p>Coba kata lain.</p></div>'}
function unitPicker(){if(!isHO())return;picker('unit','Pilih unit',[['all','Semua unit','1 HO termasuk DC + 13 store'],...units.map(u=>[u.id,u.name,u.desc])])}
function pick(value){const kind=state.picker.kind;$('#picker').close();if(kind==='unit'){state.unit=value;state.dept='all';state.query='';render()}else if(kind==='dept'){state.dept=value;render()}else if(kind==='role'){state.role=value==='store'?'store':'ho';state.actor=value==='maya'?'maya':'sarah';state.unit=value==='store'?'s01':'all';state.dept='all';state.status='all';state.kind='all';state.query='';if($('#sheet').open)$('#sheet').close();state.form=null;render();toast('Peran demo diubah')}else if(kind==='status'){state.status=value;render()}else if(kind==='kind'){state.kind=value;render()}else if(kind==='create'){openForm(value)}else if(kind==='discard'){if(value==='discard'){state.form=null;$('#sheet').close();state.detail=null}}else if(kind==='period'){state.period=value;render()}else if(kind==='workspace'){toast('Prototype ini berfokus pada workspace People')} }
function facts(pairs){return `<div class="facts">${pairs.map(([label,value])=>`<div class="fact"><small>${label}</small><strong>${value}</strong></div>`).join('')}</div>`}
function openRequest(id){const r=requests.find(x=>x.id===id);if(!r||!scoped(r))return;state.form=null;state.detail={type:'request',id};const central=!['leave','overtime','correction'].includes(r.type),owner=central?'HR HO':r.unit==='ho'?'HR HO · operasional':'HR '+unitName(r.unit);let specifics='';if(r.type==='adjustment'){const base=person(r.employee)?.salary||4500000;const signed=r.effect==='deduct'?-r.amount:r.amount;specifics=`<div class="detail-card"><h3>Usulan komponen ${r.effect==='deduct'?'pengurang':'penambah'} gaji</h3>${facts([['Nama komponen',esc(r.component)],['Periode',esc(r.period||'September 2026')],['Jenis',r.effect==='deduct'?'Pengurang (−)':'Penambah (+)'],['Berlaku',r.frequency==='recurring'?'Berulang · perlu kesepakatan HO':'Sekali pada periode ini']])}<div class="change-line" style="margin-top:16px"><span>Nominal yang diusulkan</span><strong style="color:${r.effect==='deduct'?'var(--red)':'var(--green)'}">${signed<0?'−':'+'} ${money(r.amount)}</strong></div><div class="change-line"><span>Gaji pokok contoh</span><strong>${money(base)}</strong></div><div class="change-line"><span>Subtotal setelah komponen ini</span><strong>${money(base+signed)}</strong></div><p class="sub" style="margin-top:15px">Pratinjau dampak, bukan take-home pay final. Komponen lain, kewajiban, dan potongan belum dihitung di sini.</p></div><div class="notice">${icon('shield')}${r.status==='approved'?'Usulan disetujui HO dan siap menjadi sumber perhitungan sesuai periode berlaku.':'Komponen baru masih usulan. HO memutuskan kelayakan, nominal, dan periode berlaku sebelum menjadi input payroll.'} Versi payroll yang sudah dikunci tidak diubah.</div>`}else if(r.type==='salary')specifics=`<div class="detail-card"><h3>Perubahan yang diusulkan</h3><div class="change-line"><span>Gaji pokok saat ini</span><strong>${money(r.before||4500000)}</strong></div><div class="change-line"><span>Gaji pokok usulan</span><strong style="color:var(--blue)">${money(r.amount)}</strong></div><div class="change-line"><span>Selisih per bulan</span><span>${money(r.amount-(r.before||4500000))}</span></div><p class="sub" style="margin-top:13px">Berlaku ${esc(r.effective)}. Persetujuan mencatat kesepakatan baru; payroll lama tidak ditimpa.</p></div>`;else if(r.type==='hire')specifics=`<div class="detail-card"><h3>Rencana penerimaan</h3>${facts([['Jabatan',esc(r.job||'Sales associate')],['Jumlah', '1 karyawan'],['Usulan gaji pokok',money(r.amount||4500000)],['Mulai bekerja',esc(r.effective)]])}<div class="notice" style="margin:18px 0 0">${icon('info')}Persetujuan membuka proses onboarding. Karyawan dan akun belum otomatis aktif.</div></div>`;else if(r.type==='access')specifics=`<div class="detail-card"><h3>Kebutuhan akses</h3>${facts([['Aplikasi & peran',esc(r.access||'Employee · Self-service')],['Cakupan akses',unitName(r.unit)],['Berlaku mulai',esc(r.effective)],['Eksekusi',r.provisioned?'Selesai · simulasi System':'Menunggu System']])}<div class="notice" style="margin:18px 0 0">${icon('lock')}Persetujuan HR adalah keputusan kebutuhan bisnis. System tetap menerbitkan akun dan hak akses.</div></div>`;else specifics=`<div class="detail-card"><h3>Rincian ${typeLabels[r.type].toLowerCase()}</h3>${facts([['Berlaku mulai',esc(r.effective)],['Sampai / tujuan',r.to?unitName(r.to):esc(r.until||'—')],['Unit asal',unitName(r.unit)],['Dasar',r.type==='overtime'?'Perintah atasan + kesediaan karyawan':'Pengajuan berversi']])}${r.type==='offboarding'?`<div class="checklist" style="margin-top:20px">${['Serah terima pekerjaan','Pengembalian aset','Pencabutan akses oleh System','Penyelesaian hak oleh Finance'].map(t=>`<label><input type="checkbox" data-offboard="${esc(t)}" ${r.offChecks?.includes(t)?'checked':''}>${t}</label>`).join('')}</div>`:''}</div>`;
const history=r.history||[['Pengajuan dikirim',r.by+' · '+r.date],['Draf dibuat',r.by+' · '+r.date]];let foot=`<span class="quiet">Keputusan untuk versi ${r.version} · ${owner}</span>`;if(r.status==='pending'&&canDecide(r)&&r.by!==actorName())foot+=btn('Tolak','reject','danger')+btn('Kembalikan','return')+btn(icon('check')+' Setujui','approve','primary');else if(r.status==='returned'||r.status==='draft')foot+=btn('Revisi pengajuan','revise','primary');else if(r.status==='approved'&&r.type==='hire')foot+=btn('Lihat onboarding','onboarding','primary');else if(r.status==='approved'&&r.type==='offboarding')foot+=btn('Simpan checklist','save-offboard','primary');else if(r.status==='approved'&&r.type==='access')foot+=btn(r.provisioned?'Lihat hasil eksekusi':'Lihat tugas System','access-task','primary');else foot+=btn('Tutup','close-sheet');showSheet(r.name,`${typeLabels[r.type]} · ${unitName(r.unit)}${r.dept==='dc'?' / DC':''}`,`${r.reason?`<div class="notice warn">${icon('info')}<div><strong>Catatan reviewer</strong><br>${esc(r.reason)}</div></div>`:''}${r.status==='pending'&&r.by===actorName()?'<div class="notice warn">Pengaju tidak dapat menyetujui pengajuannya sendiri.</div>':''}<div class="detail-grid"><div><div class="detail-card"><h3>Informasi pengajuan</h3>${facts([['Pengaju',esc(r.by)],['Tanggal pengajuan',r.date],['Unit kerja',unitName(r.unit)],['Bagian',r.dept==='dc'?'Distribution Center':r.dept==='office'?'Kantor HO':'Store operations']])}</div>${specifics}<div class="detail-card"><h3>Alasan pengajuan</h3><p class="detail-note">${esc(r.note)}</p><span class="badge draft">Dokumen contoh · tidak ada file pribadi</span></div></div><aside><h3>Alur persetujuan</h3><div class="timeline">${history.map(([title,desc])=>`<div class="event"><strong>${esc(title)}</strong><p>${esc(desc)}</p></div>`).join('')}<div class="event"><strong>${owner}</strong><p>${r.status==='pending'?'Menunggu keputusan':statusLabels[r.status]}</p></div></div><div class="notice">${icon('shield')}Perubahan material setelah persetujuan harus diajukan sebagai versi baru.</div></aside></div>`,foot,`<span class="mono">${r.id}</span><span>Versi ${r.version}</span>${badge(r.status)}`)}
