function decision(action){const r=requests.find(x=>x.id===state.detail?.id);if(!r||r.status!=='pending'||!canDecide(r)||r.by===actorName())return;state.decision=action;showSheet(action==='approve'?'Setujui pengajuan?':action==='return'?'Kembalikan untuk revisi':'Tolak pengajuan',`${r.id} · ${r.name} · Versi ${r.version}`,`<div class="detail-card">${facts([['Jenis',typeLabels[r.type]],['Unit',unitName(r.unit)],['Versi keputusan','Versi '+r.version],['Reviewer',actorName()]])}</div><label class="field">${action==='approve'?'Catatan keputusan':'Alasan '+(action==='return'?'pengembalian':'penolakan')} <span class="required">*</span><textarea id="decision-reason" placeholder="Tuliskan alasan yang jelas untuk pengaju…"></textarea></label><p class="error" id="decision-error"></p><div class="notice">${icon('shield')}Keputusan tersimpan pada versi ini. ${action==='return'?'Pengaju dapat merevisi dan mengirim versi baru.':r.type==='access'?'Akun belum diaktifkan sampai System menjalankan tugas.':r.type==='hire'?'Onboarding dijalankan setelah pengajuan disetujui.':'Perubahan berlaku mengikuti tanggal efektif.'}</div>`,btn('Kembali ke detail','back-detail')+btn(action==='approve'?'Setujui versi ini':action==='return'?'Kembalikan pengajuan':'Tolak pengajuan','confirm-decision',action==='reject'?'danger':'primary'))}
function confirmDecision(){const r=requests.find(x=>x.id===state.detail?.id),reason=$('#decision-reason').value.trim();if(reason.length<8){$('#decision-error').textContent='Tuliskan alasan minimal 8 karakter.';return}if(!r||r.status!=='pending'||!canDecide(r)||r.by===actorName())return;r.status=state.decision==='approve'?'approved':state.decision==='return'?'returned':'rejected';r.reason=reason;r.history=r.history||[['Pengajuan dikirim',r.by+' · '+r.date]];r.history.unshift([statusLabels[r.status]+' · v'+r.version,actorName()+' · '+reason]);state.decision=null;render();openRequest(r.id);toast('Keputusan disimpan dalam sesi demo')}
