function menuMap(){showSheet('Menu final People','Satu struktur menu. Peran menentukan aksi; unit menentukan cakupan data.',`<div class="notice">${icon('building')}1 HO dengan dua bagian: Kantor HO dan DC. Ditambah 13 store. DC bukan unit organisasi ke-15.</div><div class="menu-map">${menus.map(m=>`<div class="menu-domain"><span class="badge ${m.ho?'finance':'active'}">${m.ho?'HO':'HO + Store'}</span><h3>${icon(m.icon)}${m.label}</h3><ul>${m.tabs.map(([id,label])=>`<li>${label}${id==='cost'?' · HO':''}</li>`).join('')}</ul></div>`).join('')}</div><div class="detail-card" style="margin-top:20px"><h3>Batas tanggung jawab</h3><p class="detail-note"><strong>HR unit</strong> mengelola data operasional, mengajukan karyawan/gaji/akun, dan menutup data waktu. <strong>HR HO</strong> mengurus pegawai kantor + DC, menyetujui pengajuan lintas unit, serta menyusun dan mengendalikan payroll. <strong>System</strong> mengeksekusi akses. <strong>Finance</strong> mengeksekusi pembayaran.</p><p class="detail-note">Pengajuan komponen penambah/pengurang serta gaji tetap ada di Karyawan → Perubahan. Pengajuan akun ada di Karyawan → Akun & akses. Keduanya masuk antrean keputusan yang sama di Ringkasan.</p></div>`,btn('Tutup','close-sheet')+'<a class="btn primary" href="menu-final.md" target="_blank">Buka dokumen menu '+icon('arrow')+'</a>')}
function payAction(step){if(!isHO())return;const p=payroll.find(x=>x.id===state.detail?.id),reason=$('#pay-reason')?.value.trim();if(!p)return;if(!reason||reason.length<8){$('#action-error').textContent='Tuliskan alasan minimal 8 karakter.';return}const transitions={verify:['draft','review'],approve:['review','approved'],seal:['approved','sealed'],send:['sealed','finance']},[before,after]=transitions[step];if(p.status!==before)return;if(step==='approve'&&p.verifiedBy===state.actor){$('#action-error').textContent='Verifikator tidak dapat menyetujui run yang sama.';return}p.status=after;if(step==='verify')p.verifiedBy=state.actor;if(step==='send')p.financeRef='FIN-DEMO-'+p.unit;p.reason=reason;render();payrollDetail(p.id);toast(step==='send'?'Serah terima Finance disimulasikan':'Status payroll diperbarui')}
