 'close-sheet':closeSheet,'close-picker':()=>$('#picker').close(),approve:()=>decision('approve'),return:()=>decision('return'),reject:()=>decision('reject'),'confirm-decision':confirmDecision,'back-detail':()=>openRequest(state.detail.id),
