 onboarding:()=>{const r=requests.find(r=>r.id===state.detail.id);showSheet('Onboarding · '+r.name,`${r.id} · Penerimaan disetujui`, `<div class="notice">${icon('info')}Karyawan belum aktif sampai administrasi dan penempatan selesai. Persetujuan penerimaan tetap menjadi dokumen sumber.</div><div class="detail-card"><h3>Kesiapan hari pertama</h3><div class="checklist">${['Kontrak kerja disiapkan','Penempatan & atasan dikonfirmasi','Akun diajukan ke System','Orientasi dijadwalkan'].map((label,i)=>`<label><input type="checkbox" data-onboard="${i}" ${r.checks?.[i]?'checked':''}>${label}</label>`).join('')}</div></div>`,btn('Simpan checklist','save-onboard','primary'))},
