 'save-onboard':()=>{const r=requests.find(r=>r.id===state.detail.id);r.checks=$$('[data-onboard]').map(e=>e.checked);toast('Checklist onboarding disimpan');openRequest(r.id)},
 'access-task':()=>{const r=requests.find(r=>r.id===state.detail.id);showSheet('Tugas System',r.id+' · '+r.name,`<div class="detail-card">${facts([['Keputusan HR','Disetujui · versi '+r.version],['Cakupan',unitName(r.unit)],['Peran',esc(r.access)],['Hasil',r.provisioned?'Aktif · simulasi':'Menunggu administrator System']])}</div><div class="notice">${icon('lock')}Tombol di bawah hanya mensimulasikan respons System, bukan membuat akun atau memperluas hak akses nyata.</div>`,btn('Kembali','back-detail')+btn('Simulasikan hasil System','system-demo','primary'))},
