function periodAction(reopen){const p=periods.find(x=>x.id===state.detail?.id),reason=$('#period-reason').value.trim();if(!p||reason.length<8){$('#action-error').textContent='Alasan minimal 8 karakter diperlukan.';return}if(reopen&&!isHO())return;if(!reopen&&((isHO()&&p.unit!=='ho')||(!isHO()&&p.unit!=='s01')||p.status!=='draft'))return;p.status=reopen?'draft':'closed';p.closedBy=actorName();render();periodDetail(p.id);toast(reopen?'Periode dibuka kembali':'Periode ditutup')}
const rosterEdits={};
document.addEventListener('click',e=>{const target=e.target.closest('button,a,tr[data-open]');if(!target)return;if(target.dataset.action){actions[target.dataset.action]?.();return}if(target.dataset.menu){go(target.dataset.menu);return}if(target.dataset.tab){state.tab=target.dataset.tab;state.query='';state.status='all';state.kind='all';render();return}if(target.dataset.nav){const[m,t]=target.dataset.nav.split(':');go(m,t);return}if(target.dataset.pick){pick(target.dataset.pick);return}if(target.dataset.view){state.status=target.dataset.view;render();return}if(target.dataset.open){const[type,id]=target.dataset.open.split(':');({request:openRequest,employee:employeeDetail,period:periodDetail,payroll:payrollDetail})[type]?.(id);return}if(target.dataset.setting){showSheet(target.dataset.setting,'Rancangan pengaturan · HR HO',`<div class="detail-card"><h3>Informasi yang dicatat</h3>${facts([['Lingkup','Unit / organisasi'],['Versi','Bertanggal berlaku'],['Pengaju','Pemilik kebijakan'],['Reviewer','Berbeda dari pengaju']])}</div><div class="notice">${icon('info')}Nilai kebijakan harus berasal dari keputusan resmi. Prototype ini tidak menetapkan tarif, aturan hukum, atau konfigurasi produksi.</div>`,btn('Tutup','close-sheet'))}});
document.addEventListener('change',e=>{if(!e.target.closest('#request-form'))return;const f=$('#request-form');if(e.target.name==='period'&&f.elements.effective)f.elements.effective.value=e.target.value==='September 2026'?'2026-09-30':'2026-10-31';if(e.target.name==='unit'){const u=e.target.value;f.elements.dept.value=u==='ho'?'office':'store';if(f.elements.employee)f.elements.employee.innerHTML='<option value="">Pilih karyawan</option>'+employees.filter(x=>x.unit===u).map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}if(e.target.name==='employee'){const p=person(e.target.value);if(p){f.elements.unit.value=p.unit;f.elements.dept.value=p.dept}}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){state.query=e.target.value;refreshResults()}if(e.target.id==='picker-query')$('#picker-results').innerHTML=pickerRows(e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id==='request-form'){e.preventDefault();saveForm()}if(e.target.id==='roster-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));rosterEdits[f.employee]=f;state.form=null;$('#sheet').close();render();toast('Jadwal contoh disimpan')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-open]')){e.preventDefault();e.target.click()}});
$('#sheet').addEventListener('cancel',e=>{if(state.form){e.preventDefault();showDiscard()}else{state.detail=null;state.decision=null}});
window.addEventListener('hashchange',()=>{const parts=location.hash.split('/');const m=parts[2],t=parts[3];if(menus.some(x=>x.id===m))go(m,t)});
const route=location.hash.split('/');if(visibleMenus().some(m=>m.id===route[2])){state.menu=route[2];if(tabs().some(t=>t[0]===route[3]))state.tab=route[3];else state.tab=tabs()[0][0]}render();
